const rows = $('2 Load wf_settings').all();
const map = {};
for (const item of rows) {
  const key = String(item.json.key ?? '').trim();
  if (!key) continue;
  map[key] = item.json.value;
}

const asBool = (v) => v === true || String(v).toLowerCase() === 'true';
const asNum  = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };

const tokenRows = $('2.0.0 Load wf_meta_tokens').all();
const metaTokens = {};
for (const row of tokenRows) {
  const k = String(row.json.key || '').trim();
  if (k) metaTokens[k] = String(row.json.access_token || '').trim();
}

return [{
  json: {
    parser_url: String(map.parser_url || '').replace(/\/+$/, ''),
    parser_token: String(map.parser_token || ''),
    gdrive_folder_id: String(map.gdrive_folder_id || ''),
    default_post_limit: asNum(map.default_post_limit, 10),
    report_chat_id: String(map.report_chat_id || ''),
    publish_telegram: asBool(map.publish_telegram),
    publish_facebook: asBool(map.publish_facebook),
    publish_instagram: asBool(map.publish_instagram),
    publish_vk: asBool(map.publish_vk),
    ai_model: String(map.ai_model || 'openai/gpt-4o-mini'),
    ai_fallback_to_source: asBool(map.ai_fallback_to_source),
    caption_long_mode: String(map.caption_long_mode || 'split'),
    reprocess_failed: asBool(map.reprocess_failed),
    instagram_poll_max: asNum(map.instagram_poll_max, 12),
    instagram_poll_delay: asNum(map.instagram_poll_delay, 10),
    cloudinary_cloud_name: String(map.cloudinary_cloud_name || ''),
    cloudinary_upload_preset: String(map.cloudinary_upload_preset || ''),
    cloudinary_folder: String(map.cloudinary_folder || 'n8n/instagram'),
    // v2: отбор по важности. Ключи необязательны — работают дефолты.
    importance_filter: map.importance_filter === undefined || map.importance_filter === '' ? true : asBool(map.importance_filter),
    importance_min: asNum(map.importance_min, 6),
    importance_min_video: asNum(map.importance_min_video, 4),
    min_text_length: asNum(map.min_text_length, 80),
    min_text_length_media: asNum(map.min_text_length_media, 20),
    topic_dedupe: map.topic_dedupe === undefined || map.topic_dedupe === '' ? true : asBool(map.topic_dedupe),
    topic_dedupe_hours: asNum(map.topic_dedupe_hours, 48),
    run_id: $('1.1 Init Run').first().json.run_id,
    started_at: $('1.1 Init Run').first().json.started_at,
    meta_tokens: metaTokens,
  },
}];

const rows = $input.all();
const map = {};
for (const item of rows) {
  const k = String(item.json.key ?? '').trim();
  if (!k) continue;
  map[k] = {
    system_prompt: String(item.json.system_prompt || ''),
    user_template: String(item.json.user_template || ''),
  };
}
if (!map.default) {
  // Build the placeholder markers at runtime so n8n's static linter does not flag this code.
  const open = '{' + '{', close = '}' + '}';
  map.default = {
    system_prompt: 'Ты — редактор. Перепиши пост, сохранив все факты, даты, имена, числа и места. Не выдумывай. Не упоминай Telegram и t.me. Ответь строго в JSON по схеме.',
    user_template: 'Канал: ' + open + 'channel_name' + close + '\nДата: ' + open + 'date' + close + '\nМедиа: ' + open + 'media_type' + close + '\n\n' + open + 'source_text' + close,
  };
}
// Re-attach settings so downstream nodes can see them via the same item.
const settings = $('2.0.1 Settings to map').first().json;
return [{ json: { ...settings, prompts: map } }];

const rows = $input.all();
const ctx = $('2.2.1 Prompts to map').first().json;
const out = [];
for (const item of rows) {
  const c = item.json || {};
  const active = c.active === true || String(c.active).toLowerCase() === 'true';
  if (!active) continue;
  if (!c.url) continue;
  out.push({
    json: {
      ...ctx,
      channel_key: String(c.key || ''),
      channel_url: String(c.url || ''),
      post_limit: Number(c.post_limit) > 0 ? Number(c.post_limit) : ctx.default_post_limit,
      target_tg_chat: String(c.target_tg_chat || ''),
      fb_page_id: String(c.fb_page_id || ''),
      ig_business_id: String(c.ig_business_id || ''),
      prompt_key: String(c.prompt_key || 'default'),
      channel_note: String(c.note || ''),
      meta_token_key: String(c.meta_token_key || ''),
      vk_owner_id: String(c.vk_owner_id || ''),
      vk_token_key: String(c.vk_token_key || ''),
      rewrite_lang: String(c.rewrite_lang || 'RU'),
    },
  });
}
return out;

const ctx = $('4.2 Channel context').first().json || {};
const parser = $('4.3 Fetch posts from parser').first().json || {};
const existingRows = $input.all().map(i => i.json || {});

const staticData = $getWorkflowStaticData('global');
if (!staticData.channels) staticData.channels = {};

const channelKey = String(ctx.channel_key || parser.channel || '');
const runId = String(ctx.run_id || '');

const posts = Array.isArray(parser.posts) ? parser.posts : [];

const existingByUid = new Map();

for (const row of existingRows) {
  const uid = String(row.post_uid || '').trim();
  if (!uid) continue;
  existingByUid.set(uid, {
    overall_status: String(row.overall_status || '').trim(),
    row_number: row.row_number,
  });
}

const settingsMap = $('2.0.1 Settings to map').first().json || {};
const reprocessFailedRaw = ctx.reprocess_failed ?? settingsMap.reprocess_failed;
const reprocessFailed = reprocessFailedRaw === true || String(reprocessFailedRaw) === 'true';

const newPosts = [];
const seenNewPostUids = new Set();

for (const p of posts) {
  const postId = p.id ?? p.post_id ?? '';
  const postUid = String(p.post_uid || `${channelKey}_${postId}`).trim();

  if (seenNewPostUids.has(postUid)) {
    continue;
  }
  seenNewPostUids.add(postUid);

  const existing = existingByUid.get(postUid);
  const alreadyProcessed =
    existing &&
    (!reprocessFailed || existing.overall_status !== 'failed');

  if (alreadyProcessed) {
    continue;
  }

  const sourceText = String(p.text || p.source_text || '').trim();
  const photoUrl = String(p.photo_url || '').trim();
  const videoUrl = String(p.video_url || '').trim();

  let mediaType = String(p.media_type || '').trim();
  if (!mediaType) {
    if (videoUrl) mediaType = 'video';
    else if (photoUrl) mediaType = 'photo';
    else mediaType = 'none';
  }

  newPosts.push({
    ...ctx,
    post: p,
    post_uid: postUid,
    post_id: postId,
    post_url: String(p.post_url || `https://t.me/${channelKey}/${postId}`),
    post_date: p.date || null,
    views: Number(p.views || 0),
    source_text: sourceText,
    source_text_plain: String(p.text_plain || sourceText || ''),
    source_text_html: String(p.text_html || ''),
    links: Array.isArray(p.links) ? p.links : [],
    source_text_hash: String(p.source_text_hash || ''),
    media_type: mediaType,
    photo_url: photoUrl,
    video_url: videoUrl,
  });
}

newPosts.sort((a, b) => Number(a.post_id || 0) - Number(b.post_id || 0));

staticData.channels[channelKey] = {
  run_id: runId,
  channel_key: channelKey,
  channel_url: ctx.channel_url || '',
  posts_fetched: posts.length,
  duplicates: posts.length - newPosts.length,
  posts_new: newPosts.length,
  parser_error: parser.error || '',
};

if (newPosts.length === 0) {
  return [
    {
      json: {
        ...ctx,
        __channel_done: true,
        channel_key: channelKey,
        posts_fetched: posts.length,
        duplicates: posts.length,
        posts_new: 0,
        info: 'No new posts for this channel',
      },
    },
  ];
}

return newPosts.map(p => ({ json: p }));

// Always read the original post context from the SplitInBatches node.
// 5.1 Reserve row (Google Sheets appendOrUpdate) may return only { error: '...' }
// when column names changed, which would lose all post fields.
const orig = $('5 SplitInBatches per post').item.json || {};
const reserveResult = $input.item.json || {};
// Merge: orig provides post content; reserveResult may add spreadsheetId updates.
const j = { ...orig, ...reserveResult, ...orig };
// ^^^ orig last so content fields (source_text, channel_key, etc.) are never overwritten
// by an error-only reserveResult. Spread order: orig base → reserve additions → orig wins.
const tpl = String(j.user_template || '');
// Build placeholder markers at runtime so the static linter does not see them as expressions.
const open = '{' + '{', close = '}' + '}';
const replacements = {
  [open + 'source_text' + close]: String(j.source_text || ''),
  [open + 'channel_name' + close]: String(j.channel_key || ''),
  [open + 'post_url' + close]: String(j.post_url || ''),
  [open + 'date' + close]: String(j.post_date || ''),
  [open + 'media_type' + close]: String(j.media_type || 'none'),
};
const rewriteLang = String(j.rewrite_lang || 'RU');
const langInstruction = `\n\nВАЖНО: Напиши рерайт на языке: ${rewriteLang}. Все три версии (telegram_html, facebook_text, instagram_caption) должны быть на этом языке.`;
let userMessage = tpl;
for (const [k, v] of Object.entries(replacements)) {
  userMessage = userMessage.split(k).join(v);
}
userMessage += langInstruction;
if (!userMessage.trim()) {
  // Fallback when the template is empty: feed the source text wrapped with minimal context.
  userMessage = `Канал: ${j.channel_key || ''}\nДата: ${j.post_date || ''}\nМедиа: ${j.media_type || 'none'}\n\n${j.source_text || ''}`;
}
const rawLinks = [
  ...(Array.isArray(j.links) ? j.links : []),
  ...(Array.isArray(j.post?.links) ? j.post.links : []),
];

const links = rawLinks
  .map(l => {
    if (typeof l === 'string') {
      return {
        text: '',
        url: l,
        type: /t\.me|telegram\.me/i.test(l) ? 'telegram' : 'external',
      };
    }

    return {
      text: String(l.text || l.label || l.title || '').trim(),
      url: String(l.url || l.href || '').trim(),
      type: String(l.type || '').trim() || (/t\.me|telegram\.me/i.test(String(l.url || l.href || '')) ? 'telegram' : 'external'),
    };
  })
  .filter(l => l.url);

// Убираем дубли ссылок.
const seenLinks = new Set();
const uniqueLinks = links.filter(l => {
  if (seenLinks.has(l.url)) return false;
  seenLinks.add(l.url);
  return true;
});

if (uniqueLinks.length) {
  userMessage += '\n\nСсылки из оригинального поста. Их ОБЯЗАТЕЛЬНО нужно сохранить в рерайте:\n';

  for (const l of uniqueLinks) {
    const label = l.text || l.url;
    userMessage += `- ${label}: ${l.url} (${l.type})\n`;
  }
}

// Если parser дал HTML-версию исходника, передаём её как подсказку для структуры.
// Это особенно важно для кликабельных ссылок и списков.
if (j.source_text_html) {
  userMessage += '\n\nHTML-структура оригинала для сохранения ссылок и форматирования:\n';
  userMessage += '"""\n' + String(j.source_text_html).slice(0, 12000) + '\n"""';
}
// -----------------------------------------------------------------------------
// v2: ОТБОР ПО ВАЖНОСТИ
// -----------------------------------------------------------------------------
const settings = $('2.0.1 Settings to map').first().json || {};
const numOr = (v, d) => { const x = Number(v); return Number.isFinite(x) ? x : d; };

const importanceFilter = settings.importance_filter !== false;
const isVideo = String(j.media_type || '') === 'video';
const hasMedia = isVideo || String(j.media_type || '') === 'photo';
const importanceThreshold = isVideo
  ? numOr(settings.importance_min_video, 4)
  : numOr(settings.importance_min, 6);

// Префильтр без AI: явный мусор не тратит запрос к модели.
const meaningfulText = String(j.source_text || '')
  .replace(/https?:\/\/\S+/gi, ' ')
  .replace(/[#@]\S+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const minTextLen = hasMedia
  ? numOr(settings.min_text_length_media, 20)
  : numOr(settings.min_text_length, 80);

let prefilterSkip = false;
let prefilterReason = '';
if (importanceFilter && meaningfulText.length < minTextLen) {
  prefilterSkip = true;
  prefilterReason = (isVideo ? 'video without description' : (hasMedia ? 'photo without description' : 'too short text-only post'))
    + ` (${meaningfulText.length} < ${minTextLen} chars)`;
}

// Недавно опубликованные темы для этой же аудитории (защита от повторов одной новости).
const staticData = $getWorkflowStaticData('global');
const topicKey = String(j.target_tg_chat || j.fb_page_id || j.channel_key || 'default');
const ttlMs = numOr(settings.topic_dedupe_hours, 48) * 3600 * 1000;
const nowMs = Date.now();
const recentTopics = (settings.topic_dedupe !== false && staticData.recent_topics && Array.isArray(staticData.recent_topics[topicKey]))
  ? staticData.recent_topics[topicKey].filter(t => t && t.topic && nowMs - Number(t.ts || 0) < ttlMs).slice(-30)
  : [];

if (importanceFilter && !prefilterSkip) {
  userMessage += `

═══════════════════════════════════
ДОПОЛНИТЕЛЬНО: ОЦЕНКА ВАЖНОСТИ (обязательно)
═══════════════════════════════════
Оцени, стоит ли вообще публиковать этот пост. Добавь в JSON-ответ поля:
"importance_score": целое число 1–10,
"importance_reason": коротко, почему такая оценка,
"topic_summary": одна строка до 120 символов — конкретно о чём пост (кто / что / какое событие или инструмент),
"duplicate_of_recent": true или false

Шкала:
9–10 — крупная новость, релиз, исследование; большая практическая польза; уникальный материал.
7–8 — полезный инструмент, гайд, кейс, разбор с конкретикой.
5–6 — нормальный, но проходной материал.
3–4 — слабый: мнение без фактов, пересказ без конкретики, тизер, банальщина, «вода».
1–2 — мусор: приветствия, «доброе утро», опросы, мемы без смысла, анонсы своих эфиров/стримов,
      «подписывайтесь», розыгрыши, сбор донатов, оффтоп, личные заметки автора, пустые реакции.

${isVideo
  ? 'В посте есть ВИДЕО. Видео-посты аудитория любит больше всего — оценивай их мягче: демонстрация работы нейросети, генерация, обзор, туториал, интересный ролик — это 6+ даже при коротком тексте. Но видео-мусор (реклама, приветствие, нарезка без смысла) — всё равно низкая оценка.'
  : 'В посте нет видео — оценивай строго.'}

Порог публикации для этого поста: ${importanceThreshold}.
Если importance_score < ${importanceThreshold} или duplicate_of_recent = true — НЕ пиши тексты:
rewritten_text, telegram_html, facebook_text, instagram_caption = "". skip_post при этом не ставь (это не реклама).
`;
  if (recentTopics.length) {
    userMessage += `
Недавно уже опубликованные темы:
${recentTopics.map(t => '- ' + String(t.topic).slice(0, 160)).join('\n')}

duplicate_of_recent = true — только если пост про ТО ЖЕ САМОЕ событие / релиз / новость из списка выше (а не просто похожая тема). Если пост добавляет существенно новые факты — false.
`;
  } else {
    userMessage += '\nСписок недавних тем пуст — duplicate_of_recent = false.\n';
  }
}

return {
  json: {
    ...j,
    links: uniqueLinks,
    ai_user_message: userMessage,
    importance_filter_enabled: importanceFilter,
    importance_threshold: importanceThreshold,
    prefilter_skip: prefilterSkip,
    prefilter_reason: prefilterReason,
  },
};

options.systemMessage:
={{ $('5 SplitInBatches per post').item.json.system_prompt + '\n\nКРИТИЧЕСКИ ВАЖНО: Игнорируй инструкцию "сохраняй язык оригинала". Пиши ТОЛЬКО на языке: ' + ($('5 SplitInBatches per post').item.json.rewrite_lang || 'RU') + '. Все три версии (telegram_html, facebook_text, instagram_caption) должны быть написаны на этом языке. Это требование имеет наивысший приоритет.' }}

Если в сообщении есть блок «ОЦЕНКА ВАЖНОСТИ» — добавь в JSON поля importance_score, importance_reason, topic_summary, duplicate_of_recent.

Reply ONLY with the JSON object that matches the provided schema. Do not include any extra prose or markdown fences.

parameters.jsCode:
const item = $input.item;
const base = $('5 SplitInBatches per post').item.json || {};
const current = item.json || {};

// -----------------------------------------------------------------------------
// БАЗОВЫЕ УТИЛИТЫ
// -----------------------------------------------------------------------------

function safeString(v) {
  return String(v ?? '').trim();
}

function toBool(v) {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'number') return v === 1;

  const s = safeString(v).toLowerCase();

  if (['true', '1', 'yes', 'y', 'да'].includes(s)) return true;
  if (['false', '0', 'no', 'n', 'нет', ''].includes(s)) return false;

  return Boolean(v);
}

function stripBadWrappers(text) {
  return safeString(text)
    .replace(/^=\s*/, '')
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .replace(/^"""\s*/g, '')
    .replace(/\s*"""$/g, '')
    .replace(/^["""«»']+|["""«»']+$/g, '')
    .trim();
}

function normalizeParagraphs(text) {
  return safeString(text)
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function looksLikeJsonEnvelope(text) {
  const s = stripBadWrappers(text);

  return (
    s.startsWith('{') &&
    (
      s.includes('"rewritten_text"') ||
      s.includes('"telegram_html"') ||
      s.includes('"facebook_text"') ||
      s.includes('"instagram_caption"') ||
      s.includes('"skip_post"')
    )
  );
}

function cleanTextField(text) {
  let s = safeString(text)
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  s = s
    .replace(/(^|\n)\s*Ссылка на оригинал:\s*(\n|$)/gi, '\n')
    .replace(/(^|\n)\s*🔗\s*Ссылка на оригинал:\s*(\n|$)/gi, '\n')
    .replace(/(^|\n)\s*Подробнее:\s*(\n|$)/gi, '\n')
    .replace(/(^|\n)\s*🔗\s*Подробнее:\s*(\n|$)/gi, '\n');

  if (looksLikeJsonEnvelope(s)) {
    return '';
  }

  return normalizeParagraphs(s);
}

// -----------------------------------------------------------------------------
// ПАРСИНГ AI JSON
// -----------------------------------------------------------------------------

function getRawAiPayload(input) {
  if (!input) return '';

  if (typeof input === 'string') return input;

  if (typeof input === 'object') {
    const directFields = [
      input.rewritten_text,
      input.telegram_html,
      input.facebook_text,
      input.fb_text,
      input.instagram_caption,
    ];

    for (const f of directFields) {
      if (typeof f === 'string' && looksLikeJsonEnvelope(f)) {
        return f;
      }
    }

    if (
      input.rewritten_text !== undefined ||
      input.telegram_html !== undefined ||
      input.facebook_text !== undefined ||
      input.fb_text !== undefined ||
      input.instagram_caption !== undefined ||
      input.skip_post !== undefined ||
      input.is_ad !== undefined
    ) {
      return input;
    }

    const candidates = [
      input.output,
      input.text,
      input.response,
      input.result,
      input.message,
      input.content,
      input.data,
      input.choices?.[0]?.message?.content,
    ];

    for (const c of candidates) {
      if (c === null || c === undefined) continue;
      if (typeof c === 'object') return c;

      const s = safeString(c);
      if (s) return s;
    }

    return input;
  }

  return String(input);
}

function parseLooseBoolean(value) {
  const s = safeString(value)
    .replace(/^["']|["']$/g, '')
    .trim()
    .toLowerCase();

  if (['true', '1', 'yes', 'да'].includes(s)) return true;
  if (['false', '0', 'no', 'нет', ''].includes(s)) return false;

  return false;
}

function cleanJsonishStringValue(value) {
  let v = String(value ?? '').trim();

  v = v.replace(/,\s*$/g, '').trim();

  if (
    (v.startsWith('"') && v.endsWith('"')) ||
    (v.startsWith("'") && v.endsWith("'"))
  ) {
    v = v.slice(1, -1);
  } else {
    v = v.replace(/^"/, '').replace(/"$/g, '');
  }

  return v
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '')
    .replace(/\\"/g, '"')
    .replace(/\\'/g, "'")
    .replace(/\\\\/g, '\\')
    .trim();
}

function parseJsonishObject(rawText) {
  const raw = stripBadWrappers(rawText);
  if (!raw) return null;

  const first = raw.indexOf('{');
  const last = raw.lastIndexOf('}');
  const body =
    first !== -1 && last !== -1 && last > first
      ? raw.slice(first + 1, last)
      : raw;

  const keys = [
    'rewritten_text',
    'telegram_html',
    'facebook_text',
    'fb_text',
    'instagram_caption',
    'is_ad',
    'skip_post',
    'skip_reason',
    'warnings',
    'importance_score',
    'importance_reason',
    'topic_summary',
    'duplicate_of_recent',
  ];

  const keyPattern = new RegExp(
    `"(${keys.join('|')})"\\s*:`,
    'g'
  );

  const matches = [];
  let m;

  while ((m = keyPattern.exec(body)) !== null) {
    matches.push({
      key: m[1],
      index: m.index,
      valueStart: keyPattern.lastIndex,
    });
  }

  if (!matches.length) return null;

  const out = {};

  for (let i = 0; i < matches.length; i++) {
    const cur = matches[i];
    const next = matches[i + 1];

    let rawValue = body
      .slice(cur.valueStart, next ? next.index : body.length)
      .trim();

    rawValue = rawValue.replace(/,\s*$/g, '').trim();

    if (cur.key === 'is_ad' || cur.key === 'skip_post' || cur.key === 'duplicate_of_recent') {
      out[cur.key] = parseLooseBoolean(rawValue);
      continue;
    }

    if (cur.key === 'warnings') {
      try {
        const maybe = JSON.parse(rawValue);
        out[cur.key] = Array.isArray(maybe) ? maybe : [String(maybe)];
      } catch {
        const cleaned = cleanJsonishStringValue(rawValue)
          .replace(/^\[/, '')
          .replace(/\]$/, '')
          .trim();

        out[cur.key] = cleaned
          ? cleaned
              .split(',')
              .map(x => cleanJsonishStringValue(x))
              .filter(Boolean)
          : [];
      }

      continue;
    }

    out[cur.key] = cleanJsonishStringValue(rawValue);
  }

  const hasUsefulFields = Boolean(
    out.rewritten_text ||
    out.telegram_html ||
    out.facebook_text ||
    out.fb_text ||
    out.instagram_caption ||
    out.skip_post !== undefined ||
    out.is_ad !== undefined
  );

  return hasUsefulFields ? out : null;
}

function parseJsonFromString(rawText) {
  const s = stripBadWrappers(rawText);

  if (!s) return null;

  try {
    return JSON.parse(s);
  } catch {}

  const first = s.indexOf('{');
  const last = s.lastIndexOf('}');

  if (first !== -1 && last !== -1 && last > first) {
    const candidate = s.slice(first, last + 1);

    try {
      return JSON.parse(candidate);
    } catch {}

    const jsonish = parseJsonishObject(candidate);
    if (jsonish) {
      jsonish.warnings = Array.isArray(jsonish.warnings)
        ? [...jsonish.warnings, 'jsonish_ai_response_recovered']
        : ['jsonish_ai_response_recovered'];

      return jsonish;
    }
  }

  const loose = parseJsonishObject(s);
  if (loose) {
    loose.warnings = Array.isArray(loose.warnings)
      ? [...loose.warnings, 'jsonish_ai_response_recovered']
      : ['jsonish_ai_response_recovered'];

    return loose;
  }

  return null;
}

function parseAiJson(input, depth = 0) {
  if (depth > 4) {
    return {
      rewritten_text: '',
      telegram_html: '',
      facebook_text: '',
      instagram_caption: '',
      is_ad: false,
      skip_post: true,
      skip_reason: 'AI JSON parse recursion limit',
      warnings: ['AI JSON parse recursion limit'],
    };
  }

  const raw = getRawAiPayload(input);

  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    const nestedFields = [
      raw.output,
      raw.text,
      raw.response,
      raw.result,
      raw.message,
      raw.content,
      raw.data,
      raw.choices?.[0]?.message?.content,
    ];

    if (
      raw.rewritten_text !== undefined ||
      raw.telegram_html !== undefined ||
      raw.facebook_text !== undefined ||
      raw.fb_text !== undefined ||
      raw.instagram_caption !== undefined ||
      raw.skip_post !== undefined ||
      raw.is_ad !== undefined
    ) {
      for (const f of [
        raw.rewritten_text,
        raw.telegram_html,
        raw.facebook_text,
        raw.fb_text,
        raw.instagram_caption,
      ]) {
        if (typeof f === 'string' && looksLikeJsonEnvelope(f)) {
          const parsed = parseJsonFromString(f);
          if (parsed) return parsed;
        }
      }

      return raw;
    }

    for (const n of nestedFields) {
      if (n === null || n === undefined) continue;

      if (typeof n === 'object') {
        return parseAiJson(n, depth + 1);
      }

      if (typeof n === 'string' && safeString(n)) {
        const parsed = parseJsonFromString(n);
        if (parsed) return parsed;
      }
    }
  }

  if (typeof raw === 'string') {
    const parsed = parseJsonFromString(raw);
    if (parsed) return parsed;
  }

  return {
    rewritten_text: '',
    telegram_html: '',
    facebook_text: '',
    instagram_caption: '',
    is_ad: false,
    skip_post: true,
    skip_reason: 'AI did not return valid JSON',
    warnings: ['AI JSON parse failed'],
  };
}

// -----------------------------------------------------------------------------
// HTML / TEXT HELPERS
// -----------------------------------------------------------------------------

function escapeHtmlText(s) {
  return String(s || '')
    .replace(/&(?!(amp|lt|gt|quot|apos|#39|#\d+|#x[0-9a-f]+);)/gi, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeHtmlAttr(s) {
  return String(s || '')
    .replace(/&(?!(amp|lt|gt|quot|apos|#39|#\d+|#x[0-9a-f]+);)/gi, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '')
    .replace(/>/g, '');
}

function decodeBasicEntities(s) {
  return String(s || '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function stripHtml(text) {
  return decodeBasicEntities(
    safeString(text)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<\/div>/gi, '\n')
      .replace(/<blockquote>/gi, '\n')
      .replace(/<\/blockquote>/gi, '\n\n')
      .replace(/<pre><code>/gi, '\n')
      .replace(/<\/code><\/pre>/gi, '\n')
      .replace(/<code>/gi, '')
      .replace(/<\/code>/gi, '')
      .replace(/<b>/gi, '')
      .replace(/<\/b>/gi, '')
      .replace(/<strong>/gi, '')
      .replace(/<\/strong>/gi, '')
      .replace(/<i>/gi, '')
      .replace(/<\/i>/gi, '')
      .replace(/<em>/gi, '')
      .replace(/<\/em>/gi, '')
      .replace(/<a\s+[^>]*href=["']([^"']+)["'][^>]*>(.*?)<\/a>/gis, '$2 ($1)')
      .replace(/<[^>]+>/g, '')
  )
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function hasHtmlTags(text) {
  return /<\/?(b|strong|i|em|u|s|code|pre|blockquote|a)\b/i.test(safeString(text));
}

// Список служебных фраз-хвостов которые остаются после удаления t.me-ссылок.
// Проверяем построчно — строка считается мусорной если:
// 1. Совпадает с одним из паттернов
// 2. Содержит только пунктуацию/пробелы после ключевой фразы (не несёт контента)
function isServiceOnlyLine(line) {
  const t = line.trim();
  if (!t) return true;

  // Строка содержит только пунктуацию, пробелы и символы без букв/цифр
  if (/^[^\p{L}\p{N}]+$/u.test(t)) return true;

  // Конкретные служебные фразы без полезного контента после них
  const servicePatterns = [
    /^тут\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^тут предыдущий выпуск[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^мои избранные подборки[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^мои избранные подборки и гайды[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^мои избранные[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^здесь\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^смотри\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^читай\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^подробнее\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^ещё\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^еще\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^перейти\b[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^source\s*:[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
    /^источник\s*:[^а-яёА-ЯЁa-zA-Z0-9]*$/i,
  ];

  for (const p of servicePatterns) {
    if (p.test(t)) return true;
  }

  // Строка длиной до 60 символов заканчивается на ": " + (точка/пробелы/пусто)
  // и не содержит URL — это осиротевший заголовок без содержимого
  if (
    t.length <= 70 &&
    /:\s*\.?\s*$/.test(t) &&
    !/https?:\/\//i.test(t)
  ) return true;

  return false;
}

function removeServiceLinks(text) {
  let s = safeString(text);

  // 1. Убираем t.me ссылки
  s = s
    .replace(/https?:\/\/t\.me\/\S+/gi, '')
    .replace(/https?:\/\/telegram\.me\/\S+/gi, '')
    .replace(/\bt\.me\/\S+/gi, '')
    .replace(/\btelegram\.me\/\S+/gi, '');

  // Убираем хэштеги с Telegram-ссылками вида #Слово (?q=...)
  s = s.replace(/#\S+\s*\(\?q=[^)]+\)/g, '');

  // 2. Убираем source/источник строки
  s = s
    .replace(/^source\s*:.*$/gim, '')
    .replace(/^источник\s*:.*$/gim, '');

  // 3. Построчная чистка осиротевших служебных строк
  const lines = s.split('\n');
  const cleaned = lines.filter(line => !isServiceOnlyLine(line));
  s = cleaned.join('\n');

  // 4. Финальная нормализация
  return s
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function htmlFromPlain(text) {
  const blocks = normalizeParagraphs(text)
    .split(/\n{2,}/)
    .map(x => x.trim())
    .filter(Boolean);

  if (!blocks.length) return '';

  return blocks.map((p, index) => {
    if (index === 0) {
      return `<b>${escapeHtmlText(p)}</b>`;
    }

    if (p.startsWith('>')) {
      const quote = p
        .split('\n')
        .map(x => x.replace(/^>\s*/, '').trim())
        .filter(Boolean)
        .join('\n');

      return `<blockquote>${escapeHtmlText(quote)}</blockquote>`;
    }

    return escapeHtmlText(p);
  }).join('\n\n');
}

function cleanBrokenHtmlTags(text) {
  return safeString(text)
    .replace(/https?:\/\/[^\s<>"']+\/tg-preview\?[^\s<>"']+/gi, '')
    .replace(/<a\s[^>]*$/gi, '')
    .replace(/&lt;a\s[^&]*$/gi, '')
    .replace(/<a\s+href\s*=\s*["']?[^"'>]*$/gim, '')
    .replace(/<a\s+href\s*=\s*["'][^"']*["']\s*>\s*<\/a>/gi, '')
    .replace(/\u200B/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeTelegramHtml(input) {
  let raw = cleanTextField(input);
  raw = removeServiceLinks(raw);
  raw = cleanBrokenHtmlTags(raw);

  if (!raw) return '';

  // Нормализуем одинарные переносы в двойные — и для plain text и для HTML
  raw = raw.replace(/([^\n])\n([^\n])/g, '$1\n\n$2');

  if (!hasHtmlTags(raw)) {
    raw = htmlFromPlain(raw);
  }

  raw = raw.replace(
    /(^|\n)(>\s?.+(?:\n>\s?.+)*)/g,
    (_, prefix, quoteBlock) => {
      const q = quoteBlock
        .split('\n')
        .map(line => line.replace(/^>\s?/, '').trim())
        .filter(Boolean)
        .join('\n');

      return `${prefix}<blockquote>${escapeHtmlText(q)}</blockquote>`;
    }
  );

  const allowed = new Set(['a', 'b', 'i', 'u', 's', 'code', 'pre', 'blockquote']);

  const aliases = {
    strong: 'b',
    em: 'i',
    ins: 'u',
    strike: 's',
    del: 's',
  };

  let out = '';
  const stack = [];
  const re = /<[^>]+>/g;
  let last = 0;
  let m;

  function closeTo(tag) {
    const idx = stack.lastIndexOf(tag);
    if (idx === -1) return;
    for (let i = stack.length - 1; i >= idx; i--) {
      out += `</${stack.pop()}>`;
    }
  }

  function openTag(tag, rawTag = null) {
    out += rawTag || `<${tag}>`;
    stack.push(tag);
  }

  while ((m = re.exec(raw)) !== null) {
    out += escapeHtmlText(raw.slice(last, m.index));

    const token = m[0];
    last = re.lastIndex;

    const isClose = /^<\s*\//.test(token);
    const nameMatch = token.match(/^<\s*\/?\s*([a-z0-9]+)/i);

    if (!nameMatch) continue;

    let tag = nameMatch[1].toLowerCase();
    tag = aliases[tag] || tag;

    if (tag === 'br' && !isClose) {
      out += '\n';
      continue;
    }

    if (tag === 'a') {
      if (isClose) {
        closeTo('a');
        continue;
      }

      const hrefMatch =
        token.match(/\shref\s*=\s*"([^"]+)"/i) ||
        token.match(/\shref\s*=\s*'([^']+)'/i);

      const href = hrefMatch ? String(hrefMatch[1] || '').trim() : '';

      if (/^https?:\/\//i.test(href) && !/https?:\/\/(t\.me|telegram\.me)\//i.test(href)) {
        openTag('a', `<a href="${escapeHtmlAttr(href)}">`);
      }

      continue;
    }

    if (!allowed.has(tag)) continue;

    if (isClose) {
      closeTo(tag);
    } else {
      openTag(tag);
    }
  }

  out += escapeHtmlText(raw.slice(last));

  while (stack.length) {
    out += `</${stack.pop()}>`;
  }

  out = cleanBrokenHtmlTags(out);

  return normalizeParagraphs(out);
}

function visibleLength(html) {
  return Array.from(stripHtml(html)).length;
}

function cutPlainAtWord(text, limit) {
  const plain = stripHtml(text);

  if (Array.from(plain).length <= limit) {
    return escapeHtmlText(plain);
  }

  const chars = Array.from(plain);
  let cut = chars.slice(0, limit).join('');

  const lastSpace = Math.max(
    cut.lastIndexOf(' '),
    cut.lastIndexOf('\n'),
    cut.lastIndexOf('.'),
    cut.lastIndexOf(','),
    cut.lastIndexOf(';'),
    cut.lastIndexOf(':')
  );

  if (lastSpace > 120) {
    cut = cut.slice(0, lastSpace);
  }

  return escapeHtmlText(cut.trim() + '…');
}

function splitForTextMessage(html) {
  const full = normalizeTelegramHtml(html);

  const blocks = full
    .split(/\n{2,}/)
    .map(x => x.trim())
    .filter(Boolean);

  const picked = [];

  for (const block of blocks) {
    const candidate = [...picked, block].join('\n\n');

    if (visibleLength(candidate) <= 3900) {
      picked.push(block);
    } else {
      break;
    }
  }

  let result = picked.join('\n\n').trim();

  if (!result && blocks.length) {
    result = cutPlainAtWord(blocks[0], 3900);
  }

  if (picked.length < blocks.length && result) {
    result = result.replace(/\s*…?$/, '') + '\n\n…';
  }

  return normalizeParagraphs(result);
}

function splitHtmlByParagraphs(html, captionLimit = 900, tailLimit = 3900) {
  const full = normalizeTelegramHtml(html);

  const blocks = full
    .split(/\n{2,}/)
    .map(x => x.trim())
    .filter(Boolean);

  const captionBlocks = [];
  let used = 0;

  for (const block of blocks) {
    const candidate = [...captionBlocks, block].join('\n\n');

    if (visibleLength(candidate) <= captionLimit) {
      captionBlocks.push(block);
      used++;
    } else {
      break;
    }
  }

  let caption = captionBlocks.join('\n\n').trim();

  if (!caption && blocks.length) {
    caption = cutPlainAtWord(blocks[0], captionLimit);
    used = 1;
  }

  const tailBlocks = blocks.slice(used);
  const pickedTail = [];

  for (const block of tailBlocks) {
    const candidate = [...pickedTail, block].join('\n\n');

    if (visibleLength(candidate) <= tailLimit) {
      pickedTail.push(block);
    } else {
      break;
    }
  }

  let tail = pickedTail.join('\n\n').trim();

  if (!tail && tailBlocks.length) {
    tail = cutPlainAtWord(tailBlocks[0], tailLimit);
  }

  if (pickedTail.length < tailBlocks.length && tail) {
    tail = tail.replace(/\s*…?$/, '') + '\n\n…';
  }

  return {
    full,
    caption: normalizeTelegramHtml(caption),
    tail: normalizeTelegramHtml(tail),
    message: splitForTextMessage(full),
  };
}

// -----------------------------------------------------------------------------
// ССЫЛКИ
// -----------------------------------------------------------------------------

function parseSourceJsonMaybe(v) {
  if (!v) return {};

  if (typeof v === 'object') return v;

  if (typeof v === 'string') {
    try {
      return JSON.parse(v);
    } catch {
      return {};
    }
  }

  return {};
}

function getExternalLinks(base) {
  const sourceJson = parseSourceJsonMaybe(base.source_json);
  const links = Array.isArray(base.links)
    ? base.links
    : Array.isArray(sourceJson.links)
      ? sourceJson.links
      : [];

  const fromLinks = links
    .filter(l => l && l.url)
    .filter(l => l.type !== 'telegram')
    .filter(l => /^https?:\/\//i.test(l.url))
    .filter(l => !/https?:\/\/(x\.com|twitter\.com)\/[^/]+\/status\//i.test(l.url))
    .map(l => ({
      text: safeString(l.text || l.url),
      url: safeString(l.url).replace(/&amp;/g, '&'),
    }));

  const sourceText = safeString(base.source_text || sourceJson.text || '');

  const fromText = Array.from(
    sourceText.matchAll(/https?:\/\/[^\s)]+/gi)
  )
    .map(m => m[0].replace(/&amp;/g, '&').replace(/[.,;!?]+$/g, ''))
    .filter(url => !/https?:\/\/(t\.me|telegram\.me)\//i.test(url))
    .filter(url => !/https?:\/\/(x\.com|twitter\.com)\/[^/]+\/status\//i.test(url))
    .map(url => ({ text: 'Подробнее', url }));

  const map = new Map();

  for (const l of [...fromLinks, ...fromText]) {
    if (!l.url) continue;
    if (/https?:\/\/(t\.me|telegram\.me)\//i.test(l.url)) continue;

    map.set(l.url, l);
  }

  return Array.from(map.values());
}

function appendMissingExternalLinksHtml(html, links) {
  let out = safeString(html);

  const missing = links.filter(l => {
    const u1 = l.url;
    const u2 = l.url.replace(/&/g, '&amp;');

    return !out.includes(u1) && !out.includes(u2);
  });

  if (!missing.length) return out;

  const block = missing
    .map(l => `🔗 ${escapeHtmlText(l.text)}\n${escapeHtmlText(l.url)}`)
    .join('\n\n');

  return normalizeParagraphs(out + '\n\n' + block);
}

function appendMissingExternalLinksPlain(text, links) {
  let out = safeString(text);

  const missing = links.filter(l => !out.includes(l.url));

  if (!missing.length) return out;

  const block = missing
    .map(l => `🔗 ${l.text}\n${l.url}`)
    .join('\n\n');

  return normalizeParagraphs(out + '\n\n' + block);
}

// -----------------------------------------------------------------------------
// ЭМОДЗИ И ХЭШТЕГИ
// -----------------------------------------------------------------------------

function countEmoji(text) {
  const matches = String(text || '').match(/[\u{1F300}-\u{1FAFF}]/gu);
  return matches ? matches.length : 0;
}

function addEmojiStructurePlain(text, minEmoji = 5) {
  let t = normalizeParagraphs(text);
  if (!t) return '';

  const visible = stripHtml(t);
  if (visible.length < 350) {
    minEmoji = Math.min(minEmoji, 3);
  }

  if (countEmoji(t) >= minEmoji) return t;

  const emoji = ['💡', '🔍', '📌', '⚙️', '✅', '🚀', '🧠', '🔗', '⚠️'];
  const blocks = t.split(/\n{2,}/).map(x => x.trim()).filter(Boolean);

  let added = countEmoji(t);
  let e = 0;

  for (let i = 0; i < blocks.length && added < minEmoji; i++) {
    if (/^[\u{1F300}-\u{1FAFF}]/u.test(blocks[i])) continue;
    if (/^#/.test(blocks[i])) continue;

    blocks[i] = `${emoji[e % emoji.length]} ${blocks[i]}`;
    added++;
    e++;
  }

  return normalizeParagraphs(blocks.join('\n\n'));
}

function addEmojiStructureHtml(html, minEmoji = 5) {
  let t = normalizeTelegramHtml(html);
  if (!t) return '';

  const visible = stripHtml(t);

  if (visible.length < 350) {
    minEmoji = Math.min(minEmoji, 3);
  }

  if (countEmoji(t) >= minEmoji) return t;

  const emoji = ['💡', '🔍', '📌', '⚙️', '✅', '🚀', '🧠', '🔗', '⚠️'];
  const blocks = t.split(/\n{2,}/).map(x => x.trim()).filter(Boolean);

  let added = countEmoji(t);
  let e = 0;

  for (let i = 0; i < blocks.length && added < minEmoji; i++) {
    if (/^[\u{1F300}-\u{1FAFF}]/u.test(stripHtml(blocks[i]))) continue;
    if (/^<pre>|^<blockquote>/i.test(blocks[i])) continue;

    blocks[i] = `${emoji[e % emoji.length]} ${blocks[i]}`;
    added++;
    e++;
  }

  return normalizeTelegramHtml(blocks.join('\n\n'));
}

function normalizeHashtagsBlock(text, fallbackTags = ['#AI', '#Технологии']) {
  let t = safeString(text);
  if (!t) return t;

  t = t.replace(/([^\s\n])(\s*#\p{L}[\p{L}\p{N}_-]*)/gu, '$1\n\n$2');

  const tags = t.match(/#\p{L}[\p{L}\p{N}_-]*/gu) || [];

  if (!tags.length) {
    return normalizeParagraphs(t + '\n\n' + fallbackTags.join(' '));
  }

  let body = t
    .replace(/#\p{L}[\p{L}\p{N}_-]*/gu, '')
    .replace(/[ \t]+/g, ' ');

  body = normalizeParagraphs(body);

  const uniqueTags = [...new Set(tags)];

  return normalizeParagraphs(body + '\n\n' + uniqueTags.join(' '));
}

function limitInstagramCaption(text, max = 1500) {
  let t = normalizeParagraphs(text);

  // Заменяем двойные переносы на разделитель с невидимым символом Брайля (U+2800)
  // чтобы Instagram сохранял абзацы при публикации
  t = t.replace(/\n\n/g, '\n⠀\n');

  if (Array.from(t).length <= max) return t;

  // Для подсчёта длины и обрезки работаем с оригинальными переносами
  const tForCalc = t.replace(/\n⠀\n/g, '\n\n');
  const blocks = tForCalc.split(/\n{2,}/).map(x => x.trim()).filter(Boolean);

  let hashtags = '';
  let bodyBlocks = blocks;

  if (blocks.length && /^#/.test(blocks[blocks.length - 1])) {
    hashtags = blocks[blocks.length - 1];
    bodyBlocks = blocks.slice(0, -1);
  }

  const reserved = hashtags ? Array.from(hashtags).length + 4 : 1;
  const bodyLimit = Math.max(300, max - reserved);

  let body = bodyBlocks.join('\n\n');
  const chars = Array.from(body);

  if (chars.length > bodyLimit) {
    let cut = chars.slice(0, bodyLimit).join('');
    const lastSpace = Math.max(cut.lastIndexOf(' '), cut.lastIndexOf('\n'));

    if (lastSpace > 250) {
      cut = cut.slice(0, lastSpace);
    }

    body = cut.trim() + '…';
  }

  const result = hashtags ? `${body}\n\n${hashtags}` : body;

  // Применяем разделитель абзацев для Instagram
  return normalizeParagraphs(result).replace(/\n\n/g, '\n⠀\n');
}

// -----------------------------------------------------------------------------
// HARD AD FILTER
// -----------------------------------------------------------------------------

function detectHardAdPost(base, ai) {
  const source = String(base.source_text || '').toLowerCase();
  const sourceStart = source.slice(0, 500);

  const rewritten = String(
    ai.rewritten_text ||
    ai.telegram_html ||
    ai.facebook_text ||
    ai.fb_text ||
    ai.instagram_caption ||
    ''
  ).toLowerCase();

  const text = `${source}\n\n${rewritten}`;

  const hasExternalLeadLink =
    /utm_source=|utm_medium=|utm_campaign=|erid=|yclid=|gclid=|fbclid=/i.test(text);

  const urgency =
    /последн(ий|яя|ее)\s+шанс|остал[а-яё]*\s+\d+\s*(день|дня|дней|час|часа|часов)|успей|успеваем|только\s+сегодня|до\s+\d+\s+[а-яё]+/i.test(text);

  const applicationOrSale =
    /подать\s+(заявк|документ)|оставить\s+заявк|записаться|поступить|регистрац|купить|скидк|промокод|марафон|курс|вебинар|консультац|набор\s+(открыт|ид[её]т)|при[её]м\s+(заявок|документов)/i.test(text);

  const promoObject =
    /шад|школ[ауы]|программ[аы]\s+обучени|курс|интенсив|марафон|вебинар|консультац|бот|закрыт(ый|ая)\s+(канал|чат)|лендинг/i.test(text);

  const hasNewsValue =
    /закон|решени[ея]|суд|правительств|официальн|исследовани|релиз|обновлени|анонсировал|сообщил|данные|отч[её]т|статистика/i.test(text);

  if (hasExternalLeadLink && urgency && applicationOrSale) {
    return {
      isAd: true,
      reason: 'рекламный пост: дедлайн/призыв к действию + заявка/поступление + промо-ссылка',
    };
  }

  if (promoObject && urgency && applicationOrSale && !hasNewsValue) {
    return {
      isAd: true,
      reason: 'рекламный пост: продвижение программы/курса/набора с призывом к действию',
    };
  }

  const financialServices =
    /обмен\s+(рублей|валют|евро|долларов)|обменяю\s+|безналичные\s+рубли|наличные\s+евро|перевод[ыи]\s+рублей|привезу\s+евро|сдаёте\s+евро/i.test(sourceStart);

  if (financialServices) {
    return { isAd: true, reason: 'реклама финансовых услуг/обмена валюты' };
  }

  const serviceAd =
    /автосервис|автомойка|детейлинг|сход.?развал|ремонт\s+(подвески|двигател|кузов)|запись\s+на\s+ремонт|звоните|whatsapp|viber|записаться\s+на/i.test(text);

  if (serviceAd) {
    return { isAd: true, reason: 'реклама услуг автосервиса/бизнеса' };
  }

  const localServicesAd =
    /химчист|клининг|профессиональная\s+уборк|натяжные\s+потолки|ремонт\s+квартир|гарантирую\s+качество/i.test(sourceStart);

  if (localServicesAd) {
    return { isAd: true, reason: 'реклама локальных услуг' };
  }

  const channelPromo =
    /подписаться.*чтобы не потеряться|дублировать.*новости|наш.*канал.*вконтакте|наш новый канал/i.test(sourceStart);

  if (channelPromo) {
    return { isAd: true, reason: 'реклама канала/перенаправление аудитории' };
  }

  return {
    isAd: false,
    reason: '',
  };
}

// -----------------------------------------------------------------------------
// ОСНОВНАЯ ЛОГИКА
// -----------------------------------------------------------------------------

const ai = parseAiJson(current);

let rewrittenText = cleanTextField(
  ai.rewritten_text ||
  ai.text ||
  ai.content ||
  ''
);

let telegramHtml = cleanTextField(
  ai.telegram_html ||
  ai.telegram_text ||
  ''
);

let facebookText = cleanTextField(
  ai.facebook_text ||
  ai.fb_text ||
  ''
);

let instagramCaption = cleanTextField(
  ai.instagram_caption ||
  ai.instagram_text ||
  ''
);

const hardAd = detectHardAdPost(base, ai);

let isAd = Boolean(toBool(ai.is_ad) || hardAd.isAd);
let skipPost = Boolean(toBool(ai.skip_post) || isAd);
let skipReason = safeString(
  hardAd.reason ||
  ai.skip_reason ||
  (isAd ? 'advertising/spam post' : '')
);

let warnings = Array.isArray(ai.warnings) ? ai.warnings.map(String) : [];

if (!telegramHtml && rewrittenText) {
  telegramHtml = rewrittenText;
}

if (!facebookText && rewrittenText) {
  facebookText = stripHtml(rewrittenText);
}

if (!instagramCaption && facebookText) {
  instagramCaption = facebookText;
}

rewrittenText = normalizeParagraphs(stripHtml(removeServiceLinks(rewrittenText)));
telegramHtml = normalizeParagraphs(removeServiceLinks(telegramHtml));
facebookText = normalizeParagraphs(stripHtml(removeServiceLinks(facebookText)));
instagramCaption = normalizeParagraphs(stripHtml(removeServiceLinks(instagramCaption)));

const externalLinks = getExternalLinks(base);

if (!skipPost) {
  if (externalLinks.length <= 3) {
    telegramHtml = appendMissingExternalLinksHtml(telegramHtml, externalLinks);
    facebookText = appendMissingExternalLinksPlain(facebookText, externalLinks);
    instagramCaption = appendMissingExternalLinksPlain(instagramCaption, externalLinks);
    rewrittenText = appendMissingExternalLinksPlain(rewrittenText, externalLinks);
  }

  telegramHtml = normalizeTelegramHtml(telegramHtml);
  telegramHtml = addEmojiStructureHtml(telegramHtml, 5);

  function countParagraphsPlain(text) {
    return normalizeParagraphs(stripHtml(text))
      .split(/\n{2,}/)
      .map(x => x.trim())
      .filter(Boolean)
      .length;
  }

  const sourceParagraphs = countParagraphsPlain(base.source_text || '');
  const tgParagraphs = countParagraphsPlain(telegramHtml || '');

  if (sourceParagraphs >= 5 && tgParagraphs <= 2) {
    warnings.push('telegram_html_collapsed_by_ai');

    // Используем только plain text из source_text — text_html содержит вложенные
    // <i><b> теги Telegram которые ломают структуру после нормализации
    telegramHtml = normalizeTelegramHtml(
      stripHtml(base.source_text || '') ||
      telegramHtml
    );

    telegramHtml = addEmojiStructureHtml(telegramHtml, 5);
  }

  facebookText = addEmojiStructurePlain(facebookText, 5);
  instagramCaption = addEmojiStructurePlain(instagramCaption, 5);

  facebookText = normalizeHashtagsBlock(
    facebookText,
    ['#AI', '#Технологии', '#Автоматизация']
  );

  instagramCaption = normalizeHashtagsBlock(
    instagramCaption,
    ['#AI', '#Технологии', '#Автоматизация', '#Бизнес', '#Инновации']
  );

  instagramCaption = limitInstagramCaption(instagramCaption, 1500);
} else {
  rewrittenText = '';
  telegramHtml = '';
  facebookText = '';
  instagramCaption = '';
}

const hasPreparedText = Boolean(
  safeString(rewrittenText) ||
  safeString(telegramHtml) ||
  safeString(facebookText) ||
  safeString(instagramCaption)
);

if (!skipPost && !hasPreparedText) {
  skipPost = true;
  skipReason = 'AI returned empty or invalid text';
  warnings.push('ai_empty_or_invalid_result');
}

const aiOk = true;

// -----------------------------------------------------------------------------
// ФИНАЛЬНАЯ ЧИСТКА МУСОРА
// -----------------------------------------------------------------------------

function removeTgPreviewGarbage(text) {
  return safeString(text)
    .replace(/https?:\/\/[^\s<>"']+\/tg-preview\?[^\s<>"']+/gi, '')
    .replace(/<a\s+href=["']https?:\/\/[^"']+\/tg-preview\?[^"']*["'][^>]*>.*?<\/a>/gis, '')
    .replace(/\u200B/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function looksLikeBadFlatText(text) {
  const t = safeString(text);
  if (t.length < 700) return false;

  const paragraphCount = (t.match(/\n\n/g) || []).length;
  const sentenceCount = (t.match(/[.!?…]\s+/g) || []).length;

  return paragraphCount < 3 && sentenceCount >= 8;
}

function htmlToReadableText(html) {
  return normalizeParagraphs(
    stripHtml(html)
      .replace(/^>\s*/gm, '• ')
      .replace(/\n\s*>\s*/g, '\n• ')
  );
}

function removeBadTgPreviewFromText(text) {
  return String(text || '')
    .replace(/[\u200B\uFEFF]\s*\(\s*https?:\/\/[^\s)]*\/tg-preview[^\)]*\)/gi, '')
    .replace(/https?:\/\/[^\s<>"']*\/tg-preview[^\s<>"']*/gi, '')
    .replace(/<a\s+href=["'][^"']*\/tg-preview[^"']*["']\s*>[\s\S]*?<\/a>/gi, '')
    .replace(/<a\s+href=["']\s*$/gi, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

rewrittenText = removeTgPreviewGarbage(rewrittenText);
telegramHtml = removeTgPreviewGarbage(telegramHtml);
facebookText = removeTgPreviewGarbage(facebookText);
instagramCaption = removeTgPreviewGarbage(instagramCaption);

telegramHtml = cleanBrokenHtmlTags(telegramHtml);
facebookText = cleanBrokenHtmlTags(facebookText);
instagramCaption = cleanBrokenHtmlTags(instagramCaption);
rewrittenText = cleanBrokenHtmlTags(rewrittenText);

if (!skipPost && looksLikeBadFlatText(facebookText)) {
  facebookText = htmlToReadableText(
    telegramHtml ||
    base.text_html ||
    base.source_text ||
    rewrittenText
  );
}

if (!skipPost && looksLikeBadFlatText(rewrittenText)) {
  rewrittenText = htmlToReadableText(
    telegramHtml ||
    base.text_html ||
    base.source_text ||
    rewrittenText
  );
}

// Финальный прогон removeServiceLinks на всех полях после всех трансформаций
if (!skipPost) {
  telegramHtml = removeBadTgPreviewFromText(telegramHtml);
  facebookText = normalizeParagraphs(removeServiceLinks(stripHtml(facebookText)));
  instagramCaption = normalizeParagraphs(removeServiceLinks(stripHtml(instagramCaption)));
  rewrittenText = normalizeParagraphs(removeServiceLinks(rewrittenText));
}

const tgParts = skipPost
  ? { full: '', caption: '', tail: '', message: '' }
  : splitHtmlByParagraphs(
      telegramHtml ||
      rewrittenText ||
      base.source_text ||
      '',
      900,
      3900
    );

// -----------------------------------------------------------------------------
// URL ДЛЯ МЕДИА
// -----------------------------------------------------------------------------

const sourceJsonObj = (() => {
  try {
    return typeof (current.source_json || base.source_json) === 'string'
      ? JSON.parse(current.source_json || base.source_json)
      : (current.source_json || base.source_json || {});
  } catch {
    return {};
  }
})();

const tgOriginalPhotoUrl = safeString(
  base.photo_url ||
  current.photo_url ||
  sourceJsonObj.photo_url ||
  ''
).replace(/&amp;/g, '&');

const igImageUrl = tgOriginalPhotoUrl;

const cloudName = safeString(
  base.cloudinary_cloud_name ||
  current.cloudinary_cloud_name ||
  'dn3b8ezpw'
);

const tgCloudinaryFetchUrl = (cloudName && tgOriginalPhotoUrl)
  ? `https://res.cloudinary.com/${cloudName}/image/fetch/f_jpg,q_auto,c_pad,w_1080,h_1350,b_white/${encodeURIComponent(tgOriginalPhotoUrl)}`
  : tgOriginalPhotoUrl;

function extractAllowedUrls(text) {
  return Array.from(
    String(text || '').matchAll(/https?:\/\/[^\s<>"']+/gi)
  )
    .map(m => m[0].replace(/&amp;/g, '&').replace(/[.,;!?]+$/g, ''))
    .filter(u => !/^https?:\/\/[^\s]*\?q=%/i.test(u))
    .filter(u => !/https?:\/\/(t\.me|telegram\.me)\//i.test(u))
    .filter(u => !/\/tg-preview/i.test(u));
}

function firstNormalExternalUrl() {
  const collected = [];

  const sources = [
    base.source_text,
    base.text,
    base.text_plain,
    base.text_html,
    current.source_text,
    current.text,
    current.text_plain,
    current.text_html,
    rewrittenText,
    telegramHtml,
    facebookText,
    instagramCaption,
  ];

  for (const s of sources) {
    const found = extractAllowedUrls(s || '');
    collected.push(...found);
  }

  return [...new Set(collected)]
    .filter(u => !/\/tg-preview/i.test(u))
    .filter(u => !/t\.me\//i.test(u))
    .filter(u => !/telegram\.me\//i.test(u))[0] || '';
}

function buildTgImagePreviewUrl(imageUrl) {
  const img = safeString(imageUrl);
  if (!img) return '';

  const parserUrl = safeString(
    base.parser_url ||
    current.parser_url ||
    'https://tg-public-channel-parser.onrender.com'
  ).replace(/\/+$/, '');

  const title = stripHtml(
    telegramHtml ||
    rewrittenText ||
    base.source_text ||
    ''
  )
    .split('\n')
    .map(x => x.trim())
    .filter(Boolean)[0] || 'Media preview';

  const uid = safeString(
    base.post_uid ||
    current.post_uid ||
    `${Date.now()}`
  );

  const version = safeString(
    base.run_id ||
    current.run_id ||
    Date.now()
  );

  return `${parserUrl}/tg-preview?uid=${encodeURIComponent(uid)}&v=${encodeURIComponent(version)}&title=${encodeURIComponent(title.slice(0, 120))}&img=${encodeURIComponent(img)}`;
}

const tgImagePreviewUrl = tgOriginalPhotoUrl
  ? buildTgImagePreviewUrl(tgOriginalPhotoUrl)
  : '';

const tgExternalPreviewUrl = !tgImagePreviewUrl
  ? firstNormalExternalUrl()
  : '';

const tgLinkPreviewUrl = tgImagePreviewUrl || tgExternalPreviewUrl || '';

// -----------------------------------------------------------------------------
// RETURN
// -----------------------------------------------------------------------------

return {
  json: {
    ...base,
    ...current,

    ai_ok: aiOk,
    ai_error: '',

    rewritten_text: skipPost ? '' : rewrittenText,

    telegram_html: skipPost ? '' : tgParts.full,
    telegram_caption_html: skipPost ? '' : tgParts.caption,
    telegram_tail_html: skipPost ? '' : tgParts.tail,
    telegram_text_html: skipPost ? '' : tgParts.message,

    facebook_text: skipPost ? '' : facebookText,
    fb_text: skipPost ? '' : facebookText,

    instagram_caption: skipPost ? '' : instagramCaption,

    ig_image_url: skipPost ? '' : igImageUrl,
    tg_image_preview_url: skipPost ? '' : tgCloudinaryFetchUrl,

    tg_original_photo_url: skipPost ? '' : tgOriginalPhotoUrl,
    tg_external_preview_url: skipPost ? '' : tgExternalPreviewUrl,
    tg_link_preview_url: skipPost ? '' : tgLinkPreviewUrl,
    tg_send_text_html: skipPost ? '' : tgParts.message,

    is_ad: isAd,
    skip_post: skipPost,
    skip_reason: skipReason,
    warnings,

    // v2: оценка важности от AI
    ai_importance_score: (() => { const m = String(ai.importance_score ?? '').match(/\d+(\.\d+)?/); return m ? Number(m[0]) : null; })(),
    ai_importance_reason: safeString(ai.importance_reason).slice(0, 300),
    ai_topic_summary: safeString(ai.topic_summary).slice(0, 200),
    ai_duplicate_of_recent: toBool(ai.duplicate_of_recent ?? false),
  },
  binary: item.binary,
};

const inputItems = $input.all();

const base = $('5 SplitInBatches per post').item.json || {};
const prepared = $('6.1 Sanitize AI text').item.json || {};

// Глобальная память workflow.
// Нужна только как защита от повторного прохода одного post_uid
// внутри одного run_id после Telegram photo/tail.
const staticData = $getWorkflowStaticData('global');

if (!staticData.tg_status_seen) {
  staticData.tg_status_seen = {};
}

// Чистим старые ключи, чтобы staticData не рос бесконечно.
const now = Date.now();
const TTL = 1000 * 60 * 60 * 24; // 24 часа

for (const [key, value] of Object.entries(staticData.tg_status_seen)) {
  if (typeof value === 'number' && now - value > TTL) {
    delete staticData.tg_status_seen[key];
  }
}

const output = [];

for (const inputItem of inputItems) {
  const api = inputItem.json || {};

  const postUid = String(
    api.post_uid ||
    prepared.post_uid ||
    base.post_uid ||
    ''
  ).trim();

  const runId = String(
    api.run_id ||
    prepared.run_id ||
    base.run_id ||
    ''
  ).trim();

  const dedupeKey = `${runId}:${postUid}:after_tg`;

  // Главный фикс:
  // если этот post_uid уже вышел из Telegram-ветки в этом run_id,
  // второй проход отрезаем, чтобы не было повторной публикации в FB/IG/Sheets.
  if (runId && postUid && staticData.tg_status_seen[dedupeKey]) {
    continue;
  }

  if (runId && postUid) {
    staticData.tg_status_seen[dedupeKey] = now;
  }

  // Если статус уже подготовлен предыдущей нодой,
  // например skip/ad или отдельная статус-нода,
  // просто пропускаем дальше один раз.
  if (api.tg_status) {
    output.push({
      json: {
        ...base,
        ...prepared,
        ...api,
      },
      binary: inputItem.binary,
    });
    continue;
  }

  const statusCode = Number(api.statusCode || api.status || 0);
  const hasHttpError = statusCode >= 400;

  const err =
    api.error ||
    api.description ||
    api.body?.error ||
    api.response?.error ||
    null;

  const ok = !hasHttpError && !err;

  output.push({
    json: {
      ...base,
      ...prepared,
      ...api,

      tg_status: ok ? 'success' : 'failed',
      tg_result: ok
        ? ('message_id: ' + String(api.message_id ?? api.result?.message_id ?? '?'))
        : ('error: ' + String(
            err?.message ||
            err ||
            api.message ||
            api.body?.message ||
            JSON.stringify(api).slice(0, 1000)
          )),
    },
    binary: inputItem.binary,
  });
}

return output;

const api = $input.item.json || {};
const base = $('5 SplitInBatches per post').item.json || {};
const prepared = $('6.1 Sanitize AI text').item.json || {};
const tgCtx = $('7.1.7 Merge TG').item.json || {};

const statusCode = Number(api.statusCode || api.status || 0);
const hasHttpError = statusCode >= 400;

const err = api.error || api.body?.error || api.response?.error || null;

let ok = false;
let result = '';

if (!hasHttpError && !err && (api.id || api.post_id || api.video_id)) {
  ok = true;
  result = 'post_id: ' + String(api.id ?? api.post_id ?? api.video_id ?? '?');
} else {
  const errMsg =
    err?.message ||
    api.message ||
    api.body?.message ||
    api.headers?.['www-authenticate'] ||
    JSON.stringify(api).slice(0, 1000);

  result = 'error: ' + errMsg;
}

return {
  json: {
    ...base,
    ...prepared,
    ...tgCtx,

    fb_status: ok ? 'success' : 'failed',
    fb_result: result,
  },
  binary: $input.item.binary,
};

const api = $input.item.json || {};
const base = $('5 SplitInBatches per post').item.json || {};
const prepared = $('6.1 Sanitize AI text').item.json || {};
// Берём tg/fb статусы из Merge FB — последней ноды перед IG веткой
const fbMerge = $('8.1.7 Merge FB').item.json || {};

const statusCode = Number(api.statusCode || api.status || 0);
const hasHttpError = statusCode >= 400;
const err = api.error || api.body?.error || api.response?.error || null;
const ok = !hasHttpError && !err && Boolean(api.id);

return {
