={{ (() => {
  if ($json.overall_status === 'skipped' || $json.skip_post === true) return 'skipped';

  if ($json.ai_ok === false && $json.overall_status === 'failed') return 'failed';

  const s = [$json.tg_status, $json.fb_status, $json.ig_status, $json.vk_status].filter(x => x && x !== 'skipped_disabled');
  const ok = s.filter(x => x === 'success').length;
  const fail = s.filter(x => x === 'failed').length;
  const skip = s.filter(x => x === 'skipped').length;

  if (!s.length) return 'failed';
  if (ok === s.length) return 'success';
  if (fail > 0 && ok === 0) return 'failed';
  if (ok > 0) return 'partial';
  if (skip === s.length) return 'skipped';

  return 'failed';
})() }}

={{ (() => {
