// Read from pre-write context; 10.1 HTTP output only contains API response envelope.
const j = $('10 Compute overall status').item.json || {};
const staticData = $getWorkflowStaticData('global');

if (!staticData.runId || staticData.runId !== j.run_id) {
  staticData.runId = j.run_id || '';
  staticData.channels = staticData.channels || {};
  staticData.posts = [];
}

if (!Array.isArray(staticData.posts)) {
  staticData.posts = [];
}

const postCounter = {
  run_id: j.run_id || '',
  channel_key: j.channel_key || '',
  post_uid: j.post_uid || '',
  post_url: j.post_url || '',
  overall_status: j.overall_status || '',
  error_message: j.error_message || '',
  tg_status: j.tg_status || '',
  fb_status: j.fb_status || '',
  ig_status: j.ig_status || '',
  vk_status: j.vk_status || '',
  tg_result: j.tg_result || '',
  fb_result: j.fb_result || '',
  ig_result: j.ig_result || '',
  vk_result: j.vk_result || '',
  skip_reason: j.skip_reason || '',
  media_type: j.media_type || '',
};

// Чтобы при ручных повторных Execute Step не плодить дубли одного post_uid.
const idx = staticData.posts.findIndex(
  p => p.run_id === postCounter.run_id && p.post_uid === postCounter.post_uid
);

if (idx >= 0) {
  staticData.posts[idx] = postCounter;
} else {
  staticData.posts.push(postCounter);
}

// v2: запоминаем опубликованные темы, чтобы не постить одну новость из разных каналов.
if (postCounter.overall_status === 'success' || postCounter.overall_status === 'partial') {
  const orig = $('5 SplitInBatches per post').item.json || {};
  const topic = String(j.ai_topic_summary || '').trim();
  if (topic) {
    const key = String(orig.target_tg_chat || orig.fb_page_id || orig.channel_key || 'default');
    const hours = Number($('2.0.1 Settings to map').first().json.topic_dedupe_hours) || 48;
    const now = Date.now();
    if (!staticData.recent_topics || typeof staticData.recent_topics !== 'object') staticData.recent_topics = {};
    const list = (Array.isArray(staticData.recent_topics[key]) ? staticData.recent_topics[key] : [])
      .filter(t => t && now - Number(t.ts || 0) < hours * 3600 * 1000);
    list.push({ ts: now, topic: topic.slice(0, 200), post_uid: postCounter.post_uid });
    staticData.recent_topics[key] = list.slice(-100);
  }
}

return $input.item;

const staticData = $getWorkflowStaticData('global');
const ctx = $('2.2.1 Prompts to map').first().json || {};
const runId = ctx.run_id || staticData.runId || '';

const allChannels = staticData.channels || {};
const channelsArr = Object.values(allChannels)
  .filter(c => !runId || c.run_id === runId);

const posts = (staticData.posts || [])
  .filter(p => !runId || p.run_id === runId);

const totals = channelsArr.reduce((a, c) => {
  a.posts_fetched += Number(c.posts_fetched || 0);
  a.duplicates    += Number(c.duplicates || 0);
  a.posts_new     += Number(c.posts_new || 0);
  return a;
}, { posts_fetched: 0, duplicates: 0, posts_new: 0 });

const success = posts.filter(p => p.overall_status === 'success').length;
const partial = posts.filter(p => p.overall_status === 'partial').length;
const failed  = posts.filter(p => p.overall_status === 'failed').length;
const skipped = posts.filter(p => p.overall_status === 'skipped').length;

let status = 'success';
if (failed > 0 && success === 0 && partial === 0) {
  status = 'failed';
} else if (failed > 0 || partial > 0) {
  status = 'partial';
}
if (posts.length === 0 && totals.posts_new === 0) {
  status = 'success';
}

// Определяем нужно ли писать в таблицу
// Пишем только если:  были реальные ошибки
const hasRealErrors = posts.some(p =>
  p.tg_status === 'failed' ||
  p.fb_status === 'failed' ||
  (p.ig_status === 'failed' && !/rate limit|request limit/i.test(p.ig_result || '')) ||
  p.vk_status === 'failed'
);

const shouldLog = hasRealErrors || status === 'failed';

// Иконка статуса
const statusIcon = {
  success: '✅',
  partial: '⚠️',
  failed:  '❌',
}[status] || '❓';

// Форматирование времени: ISO → читаемый вид
function fmtTime(iso) {
  if (!iso) return '—';
  try {
    const d = new Date(iso);
    return d.toLocaleString('ru-RU', {
      timeZone: 'Europe/Moscow',
      day:    '2-digit',
      month:  '2-digit',
      year:   'numeric',
      hour:   '2-digit',
      minute: '2-digit',
      second: '2-digit',
    }).replace(',', '');
  } catch {
    return iso;
  }
}

// Длительность в секундах
function duration(start, end) {
  try {
    const s = new Date(start);
    const e = new Date(end);
    const sec = Math.round((e - s) / 1000);
    if (sec < 60) return sec + ' сек';
    return Math.floor(sec / 60) + ' мин ' + (sec % 60) + ' сек';
  } catch {
    return '—';
  }
}

const startedAt  = ctx.started_at || staticData.started_at || '';
const finishedAt = new Date().toISOString();

const lines = [];

// Заголовок
lines.push(statusIcon + ' <b>tg-ai-multipost v2</b> — ' + status);
lines.push('');

// Время
lines.push('🕐 <b>Старт:</b> ' + fmtTime(startedAt));
lines.push('🏁 <b>Финиш:</b> ' + fmtTime(finishedAt));
lines.push('⏱ <b>Время:</b> ' + duration(startedAt, finishedAt));
lines.push('');

// Счётчики
lines.push('📊 <b>Итоги</b>');
lines.push('├ Каналов: <b>' + channelsArr.length + '</b>');
lines.push('├ Постов получено: <b>' + totals.posts_fetched + '</b>');
lines.push('├ Дублей: <b>' + totals.duplicates + '</b>');
lines.push('└ Новых постов: <b>' + totals.posts_new + '</b>');
lines.push('');

// Результаты публикации (только если были новые посты)
if (totals.posts_new > 0) {
  const resultParts = [];
  if (success > 0) resultParts.push('✅ ' + success);
  if (partial > 0) resultParts.push('⚠️ ' + partial);
  if (failed  > 0) resultParts.push('❌ ' + failed);
  if (skipped > 0) resultParts.push('⏭ ' + skipped);
  lines.push('📤 <b>Публикация:</b> ' + resultParts.join('  '));
  lines.push('');
}

// По каналам
if (channelsArr.length) {
  lines.push('📡 <b>Каналы</b>');
  for (const c of channelsArr) {
    const hasError = c.parser_error;
    const errText = hasError
      ? ' — ' + (typeof c.parser_error === 'object'
          ? JSON.stringify(c.parser_error)
          : String(c.parser_error))
      : '';
    const icon = hasError ? '⚠️' : (Number(c.posts_new) > 0 ? '🟢' : '⚪');
    lines.push(
      icon + ' <b>' + (c.channel_key || '?') + '</b>' +
      ': +' + Number(c.posts_new || 0) + ' new' +
      ', ' + Number(c.posts_fetched || 0) + ' fetched' +
      ', ' + Number(c.duplicates || 0) + ' dup' +
      errText
    );
  }
  lines.push('');
}

// Ошибки по постам
const postErrors = posts.filter(p =>
  p.overall_status !== 'skipped' && (
    p.overall_status === 'failed' ||
    p.overall_status === 'partial' ||
    p.error_message
  )
);

if (postErrors.length) {
  lines.push('🔴 <b>Ошибки</b>');
  for (const e of postErrors.slice(0, 15)) {
    const channel = e.channel_key || '?';
    const uid = e.post_uid || '?';

    // Собираем ошибки по платформам
    const platformErrors = [];
    if (e.tg_status === 'failed')  platformErrors.push('TG: ' + (e.tg_result  || '').replace(/^error:\s*/i, '').slice(0, 80));
    if (e.fb_status === 'failed')  platformErrors.push('FB: ' + (e.fb_result  || '').replace(/^error:\s*/i, '').slice(0, 80));
    if (e.ig_status === 'failed')  platformErrors.push('IG: ' + (e.ig_result  || '').replace(/^error:\s*/i, '').slice(0, 80));
    if (e.vk_status === 'failed')  platformErrors.push('VK: ' + (e.vk_result  || '').replace(/^error:\s*/i, '').slice(0, 80));

    const errMsg = platformErrors.length
      ? platformErrors.join(' | ')
      : (e.error_message || '').slice(0, 150);

    lines.push('• <b>' + channel + '</b> / <code>' + uid + '</code>');
    if (errMsg) lines.push('  └ ' + errMsg);
  }
  if (postErrors.length > 15) {
    lines.push('  … и ещё ' + (postErrors.length - 15) + ' ошибок');
  }
}

// Скипнутые AI-фильтром
const skippedPosts = posts.filter(p => p.overall_status === 'skipped');
if (skippedPosts.length) {
  lines.push('');
  lines.push('⏭ <b>Пропущено (' + skippedPosts.length + ')</b>');
  for (const s of skippedPosts.slice(0, 10)) {
    lines.push('• <code>' + (s.post_uid || '?') + '</code>' +
      (s.skip_reason ? ' — ' + String(s.skip_reason).slice(0, 120).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') : ''));
  }
  if (skippedPosts.length > 10) {
    lines.push('  … и ещё ' + (skippedPosts.length - 10));
  }
}

const reportText = lines.join('\n');

// Сброс static data для следующего запуска
staticData.channels   = {};
staticData.posts      = [];
staticData.runId      = '';
staticData.started_at = '';

return [{
  json: {
    run_id:         runId,
    started_at:     startedAt,
    finished_at:    finishedAt,
    status,
    channels_total: channelsArr.length,
    posts_fetched:  totals.posts_fetched,
    duplicates:     totals.duplicates,
    posts_new:      totals.posts_new,
    success,
    partial,
    failed,
    skipped,
    report_text:    reportText,
    report_chat_id: ctx.report_chat_id,
    should_log: shouldLog,
  },
}];

const item = $input.item;
const base = $('5 SplitInBatches per post').item.json || {};

item.json = {
  ...base,
  ...item.json,
};

if (!item.binary || !item.binary.data) {
  throw new Error('No video binary data. Telegram video_url was not downloaded.');
}

const postUid = base.post_uid || item.json.post_uid || 'ig-video';

// Клонируем binary чтобы не мутировать оригинал
item.binary = {
  data: {
    ...item.binary.data,
    fileName: `${postUid}.mp4`,
    fileExtension: 'mp4',
    mimeType: 'video/mp4',
  }
};

return item;

const upload = $input.item.json || {};
const base = $('5 SplitInBatches per post').item.json || {};

if (!upload.secure_url) {
  throw new Error(
    'Cloudinary upload failed: secure_url is missing. Response: ' +
    JSON.stringify(upload).slice(0, 1000)
  );
}

const rawUrl = upload.secure_url;

// Делаем Instagram-friendly MP4:
// - f_mp4: итоговый формат mp4
// - vc_h264: H.264 video codec
// - ac_aac: AAC audio codec
// - q_auto: автоматическое качество
// - c_pad,w_1080,h_1920,b_black: вертикальное полотно 1080x1920 с чёрными полями,
//   чтобы не обрезать скринкаст/горизонтальное видео
const transformedUrl = rawUrl.replace(
  '/video/upload/',
  '/video/upload/f_mp4,vc_h264,ac_aac,q_auto,c_pad,w_1080,h_1920,b_black/'
);

return {
  json: {
    ...base,
    ig_video_url: transformedUrl,
    cloudinary_raw_url: rawUrl,
    cloudinary_public_id: upload.public_id || '',
    cloudinary_resource_type: upload.resource_type || '',
  },
};

const items = $input.all();

const init = items[0]?.json || {};
const staticData = $getWorkflowStaticData('global');

staticData.runId = init.run_id || '';
staticData.started_at = init.started_at || '';
staticData.channels = {};
staticData.posts = [];
staticData.ig_poll = {};

return items;;

const item = $input.item;

const base = $('5 SplitInBatches per post').item.json || {};
const prepared = $('6.1 Sanitize AI text').item.json || {};

function safeString(v) {
  return String(v ?? '').trim();
}

function splitHtmlAtLimit(html, limit) {
  if (html.length <= limit) return [html, ''];

  // Режем по последнему абзацу до лимита
  const chunk = html.slice(0, limit);
  const lastBreak = Math.max(
    chunk.lastIndexOf('\n\n'),
    chunk.lastIndexOf('\n')
  );
  const cutAt = lastBreak > limit * 0.5 ? lastBreak : limit;

  const caption = html.slice(0, cutAt).trim();
  const tail = html.slice(cutAt).trim();
  return [caption, tail];
}

const rawPhotoUrl = safeString(base.photo_url || '').replace(/&amp;/g, '&');

const fullHtml = safeString(
  prepared.telegram_html ||
  prepared.rewritten_text ||
  base.source_text ||
  ''
).replace(/\n{3,}/g, '\n\n');

const CAPTION_LIMIT = 1024;

const [captionHtml, tailHtml] = splitHtmlAtLimit(fullHtml, CAPTION_LIMIT);

item.json = {
  ...base,
  ...prepared,
  tg_photo_url: rawPhotoUrl,
  tg_caption_html: captionHtml,
  tg_tail_html: tailHtml,
};

return item;

const base = $('5 SplitInBatches per post').item.json || {};
const prepared = $('6.1 Sanitize AI text').item.json || {};
const igMerge = $('9.1.9 Merge IG').item.json || {};
const api = $input.item.json || {};

const vkError = api.error || null;
const hasHttpError = Number(api.statusCode || 0) >= 400;

let ok = false;
let result = '';

if (vkError) {
  ok = false;
  result = 'error: ' + String(vkError.error_msg || vkError.message || JSON.stringify(vkError)).slice(0, 300);
} else if (hasHttpError) {
  ok = false;
  result = 'error: HTTP ' + api.statusCode;
} else if (api.response && api.response.post_id) {
  ok = true;
  result = 'post_id: ' + api.response.post_id;
} else if (api.response && (api.response.video_id || api.response.id)) {
  ok = true;
  result = 'video_id: ' + (api.response.video_id || api.response.id);
} else if (api.response && typeof api.response === 'object') {
  ok = true;
  result = 'ok: ' + JSON.stringify(api.response).slice(0, 200);
} else {
  ok = false;
  result = 'error: unexpected response: ' + JSON.stringify(api).slice(0, 200);
}

return [{
  json: {
    ...base,
    ...prepared,
    tg_status: igMerge.tg_status || '',
    tg_result: igMerge.tg_result || '',
    fb_status: igMerge.fb_status || '',
    fb_result: igMerge.fb_result || '',
    ig_status: igMerge.ig_status || '',
    ig_result: igMerge.ig_result || '',
    vk_status: ok ? 'success' : 'failed',
    vk_result: result,
  },
  binary: $input.item.binary,
}];

const item = $input.item;
const videoUrl = item.json.video_url || '';

const isFakeVideo = 
  videoUrl.includes('drive.google.com') ||
  videoUrl.includes('youtube.com') ||
  videoUrl.includes('youtu.be');

if (isFakeVideo) {
  item.json.video_url = '';
  item.json.media_type = item.json.photo_url ? 'photo' : 'text';
}

return item;

// v2: решение публиковать/нет по оценке важности от AI.
// Порог: importance_min_video для видео, importance_min для остальных (wf_settings).
const item = $input.item;
const j = { ...(item.json || {}) };

if (j.importance_filter_enabled === true && j.skip_post !== true) {
  const score = j.ai_importance_score;
  const thr = Number(j.importance_threshold) || 0;
  const reason = String(j.ai_importance_reason || '').slice(0, 150);

  if (j.ai_duplicate_of_recent === true) {
    j.skip_post = true;
    j.skip_reason = 'duplicate of recent topic: ' + String(j.ai_topic_summary || '').slice(0, 120);
  } else if (typeof score === 'number' && score > 0 && score < thr) {
    j.skip_post = true;
    j.skip_reason = `low importance ${score}/10 (min ${thr}${j.media_type === 'video' ? ', video' : ''})` + (reason ? ': ' + reason : '');
  } else if (typeof score !== 'number') {
    j.warnings = [...(Array.isArray(j.warnings) ? j.warnings : []), 'ai_importance_score_missing'];
  }
}

// AI оценил низко и не написал тексты — 6.1 ставит общую причину; уточняем её.
if (j.skip_post === true && /AI returned empty or invalid text/.test(String(j.skip_reason || '')) && typeof j.ai_importance_score === 'number') {
  const thr = Number(j.importance_threshold) || 0;
  if (j.ai_duplicate_of_recent === true) {
    j.skip_reason = 'duplicate of recent topic: ' + String(j.ai_topic_summary || '').slice(0, 120);
  } else if (j.ai_importance_score < thr) {
    j.skip_reason = `low importance ${j.ai_importance_score}/10 (min ${thr})` + (j.ai_importance_reason ? ': ' + String(j.ai_importance_reason).slice(0, 150) : '');
  }
}

return { json: j, binary: item.binary };

// v2: счётчик опроса IG-контейнера. Повторяем, пока статус не FINISHED,
// не ERROR/EXPIRED и не исчерпан instagram_poll_max.
const j = $input.item.json || {};
const base = $('5 SplitInBatches per post').item.json || {};
const staticData = $getWorkflowStaticData('global');
if (!staticData.ig_poll || typeof staticData.ig_poll !== 'object') staticData.ig_poll = {};

const id = String(j.id || '').trim();
const status = String(j.status_code || '').toUpperCase();
const max = Math.max(1, Number(base.instagram_poll_max) || 10);

let attempt = 0;
if (id) {
  attempt = Number(staticData.ig_poll[id] || 0) + 1;
  staticData.ig_poll[id] = attempt;
}

const retry = Boolean(id) && !j.error && status !== 'ERROR' && status !== 'EXPIRED' && attempt < max;
if (!retry && id) delete staticData.ig_poll[id];

return {
  json: { ...j, ig_poll_attempt: attempt, ig_poll_max: max, ig_poll_retry: retry },
  binary: $input.item.binary,
};
